        local GuiTemplate = createColorPick()
       
        ColorPicker.new = function()
            pickerCreated = true
            local newMt = setmetatable({},{})
           
            local rootGui = GuiTemplate:Clone()
            rootGui.Parent = coreGui
            rootGui.Enabled = true
            pickerGui = rootGui.ColorPicker
            local pickerTopBar = pickerGui.TopBar
            backDrop = pickerGui.Backdrop
            local pickerFrame = pickerGui.Backdrop.Content
            local colorSpace = pickerFrame.ColorSpaceFrame.ColorSpace
            local colorStrip = pickerFrame.ColorStrip
            local previewFrame = pickerFrame.Preview
            local basicColorsFrame = pickerFrame.BasicColors
            local customColorsFrame = pickerFrame.CustomColors
            local okButton = pickerFrame.Ok
            local cancelButton = pickerFrame.Cancel
            local closeButton = pickerTopBar.Close
   
            local colorScope = colorSpace.Scope
            local colorArrow = pickerFrame.ArrowFrame.Arrow
   
            local hueInput = pickerFrame.Hue.Input
            local satInput = pickerFrame.Sat.Input
            local valInput = pickerFrame.Val.Input
   
            local redInput = pickerFrame.Red.Input
            local greenInput = pickerFrame.Green.Input
            local blueInput = pickerFrame.Blue.Input
   
            local user = game:GetService("UserInputService")
            local mouse = game:GetService("Players").LocalPlayer:GetMouse()
           
            local hue,sat,val = Color3.toHSV(savedColor)
            local red,green,blue = savedColor.r, savedColor.g, savedColor.b
            local chosenColor = savedColor
   
            local basicColors = {Color3.new(0,0,0),Color3.new(0.66666668653488,0,0),Color3.new(0,0.33333334326744,0),Color3.new(0.66666668653488,0.33333334326744,0),Color3.new(0,0.66666668653488,0),Color3.new(0.66666668653488,0.66666668653488,0),Color3.new(0,1,0),Color3.new(0.66666668653488,1,0),Color3.new(0,0,0.49803924560547),Color3.new(0.66666668653488,0,0.49803924560547),Color3.new(0,0.33333334326744,0.49803924560547),Color3.new(0.66666668653488,0.33333334326744,0.49803924560547),Color3.new(0,0.66666668653488,0.49803924560547),Color3.new(0.66666668653488,0.66666668653488,0.49803924560547),Color3.new(0,1,0.49803924560547),Color3.new(0.66666668653488,1,0.49803924560547),Color3.new(0,0,1),Color3.new(0.66666668653488,0,1),Color3.new(0,0.33333334326744,1),Color3.new(0.66666668653488,0.33333334326744,1),Color3.new(0,0.66666668653488,1),Color3.new(0.66666668653488,0.66666668653488,1),Color3.new(0,1,1),Color3.new(0.66666668653488,1,1),Color3.new(0.33333334326744,0,0),Color3.new(1,0,0),Color3.new(0.33333334326744,0.33333334326744,0),Color3.new(1,0.33333334326744,0),Color3.new(0.33333334326744,0.66666668653488,0),Color3.new(1,0.66666668653488,0),Color3.new(0.33333334326744,1,0),Color3.new(1,1,0),Color3.new(0.33333334326744,0,0.49803924560547),Color3.new(1,0,0.49803924560547),Color3.new(0.33333334326744,0.33333334326744,0.49803924560547),Color3.new(1,0.33333334326744,0.49803924560547),Color3.new(0.33333334326744,0.66666668653488,0.49803924560547),Color3.new(1,0.66666668653488,0.49803924560547),Color3.new(0.33333334326744,1,0.49803924560547),Color3.new(1,1,0.49803924560547),Color3.new(0.33333334326744,0,1),Color3.new(1,0,1),Color3.new(0.33333334326744,0.33333334326744,1),Color3.new(1,0.33333334326744,1),Color3.new(0.33333334326744,0.66666668653488,1),Color3.new(1,0.66666668653488,1),Color3.new(0.33333334326744,1,1),Color3.new(1,1,1)}
            local customColors = {}
   
            local function updateColor(noupdate)
                local relativeX,relativeY,relativeStripY = 219 - hue*219, 199 - sat*199, 199 - val*199
                local hsvColor = Color3.fromHSV(hue,sat,val)
       
                if noupdate == 2 or not noupdate then
                    hueInput.Text = tostring(math.ceil(359*hue))
                    satInput.Text = tostring(math.ceil(255*sat))
                    valInput.Text = tostring(math.floor(255*val))
                end
                if noupdate == 1 or not noupdate then
                    redInput.Text = tostring(math.floor(255*red))
                    greenInput.Text = tostring(math.floor(255*green))
                    blueInput.Text = tostring(math.floor(255*blue))
                end
       
                chosenColor = Color3.new(red,green,blue)
       
                colorScope.Position = UDim2.new(0,relativeX-9,0,relativeY-9)
                colorStrip.ImageColor3 = Color3.fromHSV(hue,sat,1)
                colorArrow.Position = UDim2.new(0,-2,0,relativeStripY-4)
                previewFrame.BackgroundColor3 = chosenColor
       
                updateBack(chosenColor, backDrop)
               
                newMt.Color = chosenColor
                if newMt.Changed then
                    newMt:Changed(chosenColor)
                end
            end
   
            local function colorSpaceInput()
                local relativeX = mouse.X - colorSpace.AbsolutePosition.X
                local relativeY = mouse.Y - colorSpace.AbsolutePosition.Y
                   
                if relativeX < 0 then relativeX = 0 elseif relativeX > 219 then relativeX = 219 end
                if relativeY < 0 then relativeY = 0 elseif relativeY > 199 then relativeY = 199 end
                   
                hue = (219 - relativeX)/219
                sat = (199 - relativeY)/199
       
                local hsvColor = Color3.fromHSV(hue,sat,val)
                red,green,blue = hsvColor.r,hsvColor.g,hsvColor.b
       
                updateColor()
            end
   
            local function colorStripInput()
                local relativeY = mouse.Y - colorStrip.AbsolutePosition.Y
       
                if relativeY < 0 then relativeY = 0 elseif relativeY > 199 then relativeY = 199 end
       
                val = (199 - relativeY)/199
       
                local hsvColor = Color3.fromHSV(hue,sat,val)
                red,green,blue = hsvColor.r,hsvColor.g,hsvColor.b
       
                updateColor()
            end
   
            local function hookButtons(frame,func)
                frame.ArrowFrame.Up.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseMovement then
                        frame.ArrowFrame.Up.BackgroundTransparency = 0.5
                    elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
                        local releaseEvent,runEvent
               
                        local startTime = tick()
                        local pressing = true
                        local startNum = tonumber(frame.Text)
               
                        if not startNum then return end
               
                        releaseEvent = user.InputEnded:Connect(function(input)
                            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                            releaseEvent:Disconnect()
                            pressing = false
                        end)
               
                        startNum = startNum + 1
                        func(startNum)
                        while pressing do
                            if tick()-startTime > 0.3 then
                                startNum = startNum + 1
                                func(startNum)
                            end
                            wait(0.1)
                        end
                    end
                end)
       
                frame.ArrowFrame.Up.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseMovement then
                        frame.ArrowFrame.Up.BackgroundTransparency = 1
                    end
                end)
       
                frame.ArrowFrame.Down.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseMovement then
                        frame.ArrowFrame.Down.BackgroundTransparency = 0.5
                    elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
                        local releaseEvent,runEvent
               
                        local startTime = tick()
                        local pressing = true
                        local startNum = tonumber(frame.Text)
               
                        if not startNum then return end
               
                        releaseEvent = user.InputEnded:Connect(function(input)
                            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                            releaseEvent:Disconnect()
                            pressing = false
                        end)
               
                        startNum = startNum - 1
                        func(startNum)
                        while pressing do
                            if tick()-startTime > 0.3 then
                                startNum = startNum - 1
                                func(startNum)
                            end
                            wait(0.1)
                        end
                    end
                end)
       
                frame.ArrowFrame.Down.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseMovement then
                        frame.ArrowFrame.Down.BackgroundTransparency = 1
                    end
                end)
            end
   
            colorSpace.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    local releaseEvent,mouseEvent
           
                    releaseEvent = user.InputEnded:Connect(function(input)
                        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                        releaseEvent:Disconnect()
                        mouseEvent:Disconnect()
                    end)
           
                    mouseEvent = user.InputChanged:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseMovement then
                            colorSpaceInput()
                        end
                    end)
           
                    colorSpaceInput()
                end
            end)
   
            colorStrip.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    local releaseEvent,mouseEvent
           
                    releaseEvent = user.InputEnded:Connect(function(input)
                        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                        releaseEvent:Disconnect()
                        mouseEvent:Disconnect()
                    end)
           
                    mouseEvent = user.InputChanged:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseMovement then
                            colorStripInput()
                        end
                    end)
           
                    colorStripInput()
                end
            end)
   
            local function updateHue(str)
                local num = tonumber(str)
                if num then
                    hue = math.clamp(math.floor(num),0,359)/359
                    local hsvColor = Color3.fromHSV(hue,sat,val)
                    red,green,blue = hsvColor.r,hsvColor.g,hsvColor.b
                    hueInput.Text = tostring(hue*359)
                    updateColor(1)
                end
            end
            hueInput.FocusLost:Connect(function() updateHue(hueInput.Text) end) hookButtons(hueInput,updateHue)
   
            local function updateSat(str)
                local num = tonumber(str)
                if num then
                    sat = math.clamp(math.floor(num),0,255)/255
                    local hsvColor = Color3.fromHSV(hue,sat,val)
                    red,green,blue = hsvColor.r,hsvColor.g,hsvColor.b
                    satInput.Text = tostring(sat*255)
                    updateColor(1)
                end
            end
            satInput.FocusLost:Connect(function() updateSat(satInput.Text) end) hookButtons(satInput,updateSat)
   
            local function updateVal(str)
                local num = tonumber(str)
                if num then
                    val = math.clamp(math.floor(num),0,255)/255
                    local hsvColor = Color3.fromHSV(hue,sat,val)
                    red,green,blue = hsvColor.r,hsvColor.g,hsvColor.b
                    valInput.Text = tostring(val*255)
                    updateColor(1)
                end
            end
            valInput.FocusLost:Connect(function() updateVal(valInput.Text) end) hookButtons(valInput,updateVal)
           
            local function updateRed(str)
                local num = tonumber(str)
                if num then
                    red = math.clamp(math.floor(num),0,255)/255
                    local newColor = Color3.new(red,green,blue)
                    hue,sat,val = Color3.toHSV(newColor)
                    redInput.Text = tostring(red*255)
                    updateColor(2)
                end
            end
            redInput.FocusLost:Connect(function() updateRed(redInput.Text) end) hookButtons(redInput,updateRed)
           
