            end
        end
    end
   
    local function playSong(id)
        stopSounds()
        local sound = Instance.new("Sound")
        sound.Parent = lighting
        sound.SoundId = "rbxassetid://"..tostring(id)
        sound.Volume = volume
        sound.Name = "RoseHubSound"
        sound.Looped = true
        sound.Playing = true
    end
   
