    wait(0.5)
   
    intro:Destroy()
   
    gui.Enabled = true
   
    gui.Open:TweenPosition(UDim2.new(0, 0, 0.75, 0), "Out", "Quad", 0.5)
    wait(0.5)
   
    tweening = false
   
    print("Rose Hub process finished at " .. round(tick()-start) .. " milliseconds.")
end)

