local function GetFunc(t, i)
    for __, ___ in next, (t) do
        if string.lower(i):match(__:lower()) then
            return ___, __
        end
    end
end
 
local function GetColor(t, i)
    for __, ___ in next, (t) do
        if (___[1] == i) then
            return ___, __
        elseif (___[2] == i) then
            return ___, __
        end
    end
end
 
