for _, Log in pairs(service.Workspace.LogModels:GetChildren()) do
if Log.Name:sub(1, 6) == "Loose_" and Log:findFirstChild("Owner") then
if Log.Owner.Value == service.Players.LocalPlayer then
for i,v in pairs(Log:GetChildren()) do
if v.Name=="WoodSection" then
spawn(function()
for i=1,10 do
wait()
v.CFrame=CFrame.new(Vector3.new(315, -0.296, 85.791))*CFrame.Angles(math.rad(90),0,0)
end
end)
end
end
spawn(function()
for i=1,20 do
wait()
service.ReplicatedStorage.Interaction.ClientIsDragging:FireServer(Log)
end
end)
end
end
end
end)

TeleportToSpook.MouseButton1Click:Connect(function()
for i, v in pairs(game:GetService("Workspace"):GetChildren()) do
    if v.Name == "TreeRegion" then
        for j, k in ipairs(v:GetChildren()) do
            if k:FindFirstChild("TreeClass") and k.TreeClass.Value == "Spooky" or k:FindFirstChild("TreeClass") and k.TreeClass.Value == "SpookyNeon" then
                game:GetService("Players").LocalPlayer.Character:MoveTo(k.WoodSection.Position)
break
            end
        end
    end
end
end)

GlitchWood.MouseButton1Click:Connect(function()
if not Glitching then
Glitching=true
GlitchWood.Text="GlitchWood: On"
else
Glitching=false
GlitchWood.Text="GlitchWood: Off"
end
end)

local Pressing = false

game:GetService("Players").LocalPlayer:GetMouse().KeyDown:Connect(function(key)
    if key=="e" and Glitching then
        Pressing=true
        poop(GetAxe())
    end
end)

game:GetService("Players").LocalPlayer:GetMouse().KeyUp:Connect(function(key)
    if key=="e" then
        Pressing=false
    end
end)

function cut(Height,Tool)
local Tree=game:GetService("Players").LocalPlayer:GetMouse().Target
game:GetService("ReplicatedStorage").Interaction.RemoteProxy:FireServer(Tree.Parent.CutEvent,{
["cuttingClass"] = "Axe",
["cooldown"] = 0,
["hitPoints"] = HitPoints[Tool.ToolName.Value],
["sectionId"] = 1,
["tool"] = Tool,
["faceVector"] = Vector3.new(-1,0,0),
["height"] = Height})
end

function poop(Tool)
    while Pressing do
        for i=1,50 do
wait()
cut(tonumber(Distance.Text),Tool)
cut(1,Tool)
end
    end
end
end)

