            game:GetService("Players").LocalPlayer.Character.HumanoidRootPart.CFrame = workspace[v.Name].HumanoidRootPart.CFrame
        else
            print("Player not found")
        end
    end
end
 
generalespbutton.MouseButton1Down:connect(function()
    --credits to Nebula Hub for the esp + aimbot
    PLAYER  = game:GetService("Players").LocalPlayer
    MOUSE   = PLAYER:GetMouse()
    CC      = game:GetService("Workspace").CurrentCamera
 
    ENABLED      = false
    ESP_ENABLED  = false
 
    _G.FREE_FOR_ALL = true
 
    _G.BIND        = 50
    _G.ESP_BIND    = 52
    _G.CHANGE_AIM  = 'q'
 
    _G.AIM_AT = 'Head'
 
    wait(1)
 
    function GetNearestPlayerToMouse()
    local PLAYERS      = {}
    local PLAYER_HOLD  = {}
    local DISTANCES    = {}
    for i, v in pairs(game:GetService("Players"):GetPlayers()) do
    if v ~= PLAYER then
    table.insert(PLAYERS, v)
    end
    end
    for i, v in pairs(PLAYERS) do
    if _G.FREE_FOR_ALL == false then
    if v and (v.Character) ~= nil and v.TeamColor ~= PLAYER.TeamColor then
    local AIM = v.Character:FindFirstChild(_G.AIM_AT)
    if AIM ~= nil then
    local DISTANCE                 = (AIM.Position - game:GetService("Workspace").CurrentCamera.CoordinateFrame.p).magnitude
    local RAY                      = Ray.new(game:GetService("Workspace").CurrentCamera.CoordinateFrame.p, (MOUSE.Hit.p - CC.CoordinateFrame.p).unit * DISTANCE)
    local HIT,POS                  = game:GetService("Workspace"):FindPartOnRay(RAY, game:GetService("Workspace"))
    local DIFF                     = math.floor((POS - AIM.Position).magnitude)
    PLAYER_HOLD[v.Name .. i]       = {}
    PLAYER_HOLD[v.Name .. i].dist  = DISTANCE
    PLAYER_HOLD[v.Name .. i].plr   = v
    PLAYER_HOLD[v.Name .. i].diff  = DIFF
    table.insert(DISTANCES, DIFF)
    end
    end
    elseif _G.FREE_FOR_ALL == true then
    local AIM = v.Character:FindFirstChild(_G.AIM_AT)
    if AIM ~= nil then
    local DISTANCE                 = (AIM.Position - game:GetService("Workspace").CurrentCamera.CoordinateFrame.p).magnitude
    local RAY                      = Ray.new(game:GetService("Workspace").CurrentCamera.CoordinateFrame.p, (MOUSE.Hit.p - CC.CoordinateFrame.p).unit * DISTANCE)
    local HIT,POS                  = game:GetService("Workspace"):FindPartOnRay(RAY, game:GetService("Workspace"))
    local DIFF                     = math.floor((POS - AIM.Position).magnitude)
    PLAYER_HOLD[v.Name .. i]       = {}
    PLAYER_HOLD[v.Name .. i].dist  = DISTANCE
    PLAYER_HOLD[v.Name .. i].plr   = v
    PLAYER_HOLD[v.Name .. i].diff  = DIFF
    table.insert(DISTANCES, DIFF)
    end
    end
    end
 
    if unpack(DISTANCES) == nil then
    return false
    end
 
    local L_DISTANCE = math.floor(math.min(unpack(DISTANCES)))
    if L_DISTANCE > 20 then
    return false
    end
 
    for i, v in pairs(PLAYER_HOLD) do
    if v.diff == L_DISTANCE then
    return v.plr
    end
    end
    return false
    end
 
    GUI_MAIN                           = Instance.new('ScreenGui', game:GetService("CoreGui"))
    GUI_TARGET                         = Instance.new('TextLabel', GUI_MAIN)
    GUI_AIM_AT                         = Instance.new('TextLabel', GUI_MAIN)
 
    GUI_MAIN.Name                      = 'AIMBOT'
 
    GUI_TARGET.Size                    = UDim2.new(0,200,0,30)
    GUI_TARGET.BackgroundTransparency  = 0.5
    GUI_TARGET.BackgroundColor         = BrickColor.new('Fossil')
    GUI_TARGET.BorderSizePixel         = 0
    GUI_TARGET.Position                = UDim2.new(0.5,-100,0,0)
    GUI_TARGET.Text                    = 'AIMBOT : OFF'
    GUI_TARGET.TextColor3              = Color3.new(1,1,1)
    GUI_TARGET.TextStrokeTransparency  = 1
    GUI_TARGET.TextWrapped             = true
    GUI_TARGET.FontSize                = 'Size24'
    GUI_TARGET.Font                    = 'SourceSansBold'
 
    GUI_AIM_AT.Size                    = UDim2.new(0,200,0,20)
    GUI_AIM_AT.BackgroundTransparency  = 0.5
    GUI_AIM_AT.BackgroundColor         = BrickColor.new('Fossil')
    GUI_AIM_AT.BorderSizePixel         = 0
    GUI_AIM_AT.Position                = UDim2.new(0.5,-100,0,30)
    GUI_AIM_AT.Text                    = 'AIMING : HEAD'
    GUI_AIM_AT.TextColor3              = Color3.new(1,1,1)
    GUI_AIM_AT.TextStrokeTransparency  = 1
    GUI_AIM_AT.TextWrapped             = true
    GUI_AIM_AT.FontSize                = 'Size18'
    GUI_AIM_AT.Font                    = 'SourceSansBold'
 
    local TRACK = false
 
    function CREATE(BASE, COLOR)
