		FlyR6.Name = "Fly (R6)"
		FlyR6.Parent = MainBody
		FlyR6.BackgroundColor3 = Color3.new(0, 0.615686, 1)
		FlyR6.Position = UDim2.new(0.347598553, 0, 0.501739383, 0)
