		function shortnames(username)
			local nameshort = {}
			for i,v in pairs(game:GetService("Players"):GetPlayers()) do
				if v.Name:lower():sub(1, #username) == username:lower() then
					table.insert(nameshort,v)
				end
			end    
			return nameshort    
		end

