                }

                local Row = {
                        Font = Styles.Font;
                        FontSize = Enum.FontSize.Size14;
                        TextXAlignment = Enum.TextXAlignment.Left;
                        TextColor = Styles.Black;
                        TextColorOver = Styles.White;
                        TextLockedColor = CreateColor3(120,120,120);
                        Height = 24;
