									end
								end

								if ChosenPlayer then
									if ChosenPlayer.Character then
										pcall(function()
											game:GetService("Workspace").CurrentCamera.CameraSubject = ChosenPlayer.Character:FindFirstChildWhichIsA('Humanoid')
