		elseif gethui then
			local success,err = pcall(function()
				BruUI.ScreenGui.Parent = gethui()
			end)
			if not success and err then
				BruUI.ScreenGui.Parent = CoreGui
			end
		else
			BruUI.ScreenGui.Parent = CoreGui
		end

