		Spam.MouseButton1Click:connect(function()
			keepspam = not keepspam
			if keepspam then
				Spam.BackgroundColor3 = loc
			else
				Spam.BackgroundColor3 = col
			end
			while wait(0.5) do
				if keepspam then
					game:GetService("ReplicatedStorage").DefaultChatSystemChatEvents.SayMessageRequest:FireServer(CHATBOX.Text, "All")
				end
			end
		end)
		clip = true
		Noclip.MouseButton1Click:connect(function()
			clip = not clip
			game:GetService('RunService').Stepped:connect(function()
				if not clip then
					Noclip.BackgroundColor3 = loc
					game:GetService("Players").LocalPlayer.Character.Head.CanCollide = false
					game:GetService("Players").LocalPlayer.Character.Torso.CanCollide = false
					game:GetService("Players").LocalPlayer.Character["Left Leg"].CanCollide = false
					game:GetService("Players").LocalPlayer.Character["Right Leg"].CanCollide = false
				else
					Noclip.BackgroundColor3 = col
				end
			end)
		end)
		local flying = false
		Fly.MouseButton1Click:connect(function()
			flying = not flying
			repeat
				wait()
			until game:GetService("Players").LocalPlayer and game:GetService("Players").LocalPlayer.Character and game:GetService("Players").LocalPlayer.Character:findFirstChild("Torso") and game:GetService("Players").LocalPlayer.Character:findFirstChild("Humanoid")
			local mouse = game:GetService("Players").LocalPlayer:GetMouse()
			repeat
				wait()
			until mouse
			local plr = game:GetService("Players").LocalPlayer
			local torso = plr.Character.Torso
			local deb = true
			local ctrl = {
				f = 0,
				b = 0,
				l = 0,
				r = 0
			}
			local lastctrl = {
				f = 0,
				b = 0,
				l = 0,
				r = 0
			}
			local maxspeed = 70
			local speed = 0
			if flying then
				Fly.BackgroundColor3 = loc
			else
				Fly.BackgroundColor3 = col
			end
			function FlyFunction()
				local bg = Instance.new("BodyGyro", torso)
				bg.P = 9e4
				bg.maxTorque = Vector3.new(9e9, 9e9, 9e9)
				bg.cframe = torso.CFrame
				local bv = Instance.new("BodyVelocity", torso)
				bv.velocity = Vector3.new(0, 0.1, 0)
				bv.maxForce = Vector3.new(9e9, 9e9, 9e9)
				repeat
					wait()
					plr.Character.Humanoid.PlatformStand = true
					if ctrl.l + ctrl.r ~= 0 or ctrl.f + ctrl.b ~= 0 then
						speed = speed + .5 + (speed / maxspeed)
						if speed > maxspeed then
							speed = maxspeed
						end
					elseif not (ctrl.l + ctrl.r ~= 0 or ctrl.f + ctrl.b ~= 0) and speed ~= 0 then
						speed = speed - 1
						if speed < 0 then
							speed = 0
						end
					end
					if (ctrl.l + ctrl.r) ~= 0 or (ctrl.f + ctrl.b) ~= 0 then
						bv.velocity = ((game:GetService("Workspace").CurrentCamera.CoordinateFrame.lookVector * (ctrl.f + ctrl.b)) + ((game:GetService("Workspace").CurrentCamera.CoordinateFrame * CFrame.new(ctrl.l + ctrl.r, (ctrl.f + ctrl.b) * .2, 0).p) - game:GetService("Workspace").CurrentCamera.CoordinateFrame.p)) * speed
						lastctrl = {
							f = ctrl.f,
							b = ctrl.b,
							l = ctrl.l,
							r = ctrl.r
						}
					elseif (ctrl.l + ctrl.r) == 0 and (ctrl.f + ctrl.b) == 0 and speed ~= 0 then
						bv.velocity = ((game:GetService("Workspace").CurrentCamera.CoordinateFrame.lookVector * (lastctrl.f + lastctrl.b)) + ((game:GetService("Workspace").CurrentCamera.CoordinateFrame * CFrame.new(lastctrl.l + lastctrl.r, (lastctrl.f + lastctrl.b) * .2, 0).p) - game:GetService("Workspace").CurrentCamera.CoordinateFrame.p)) * speed
					else
						bv.velocity = Vector3.new(0, 0.1, 0)
					end
					bg.cframe = game:GetService("Workspace").CurrentCamera.CoordinateFrame * CFrame.Angles(-math.rad((ctrl.f + ctrl.b) * 50 * speed / maxspeed), 0, 0)
				until not flying
				ctrl = {
					f = 0,
					b = 0,
					l = 0,
					r = 0
				}
				lastctrl = {
					f = 0,
					b = 0,
					l = 0,
					r = 0
				}
				speed = 0
				bg:Destroy()
				bv:Destroy()
				plr.Character.Humanoid.PlatformStand = false
			end
			mouse.KeyDown:connect(function(key)
				if key:lower() == "w" then
					ctrl.f = 1
				elseif key:lower() == "s" then
					ctrl.b = -1
				elseif key:lower() == "a" then
					ctrl.l = -1
				elseif key:lower() == "d" then
					ctrl.r = 1
				end
			end)
			mouse.KeyUp:connect(function(key)
				if key:lower() == "w" then
					ctrl.f = 0
				elseif key:lower() == "s" then
					ctrl.b = 0
				elseif key:lower() == "a" then
					ctrl.l = 0
				elseif key:lower() == "d" then
					ctrl.r = 0
				end
			end)
			FlyFunction()
		end)

