Main:AddInput("TextboxIdentifier", {
	Title = "FE Play all boomboxes",
    Default = "Put Sound Id Here",
	Description = "Uses all the boomboxes in your inventory and plays them all at the same time",
    PlaceHolder = "Placeholder",
    Numeric = true,
    Finished = true,
	Callback = function(SoundId)
        local Settings = {
			[1] = "PlaySong",
			[2] = tonumber(SoundId)
		}

		for i, Boombox in next, game:GetService("Players").LocalPlayer:WaitForChild("Backpack"):GetChildren() do
			if (Boombox.Name == "Radio" or Boombox.Name == "Boombox") or (Boombox:FindFirstChild("Server") and Boombox:FindFirstChild("Client")) then
				Boombox.Parent = game:GetService("Players").LocalPlayer.Character
				Boombox.Remote:FireServer(unpack(Settings))
			end
		end
	end
})
