        sound = true
        local ID = "rbxassetid://"..sounid --your sound id here
        local Name = "name" --your sound name
        local Volume = 1000 --volume
        local Pitch = 1 --pitch

        for i,v in pairs(game:GetService("Workspace"):GetDescendants()) do
            if v:IsA("RemoteEvent") and v.Name == "AC6_FE_Sounds" then
                if sound == true then
                    v:FireServer("newSound", Name, game:GetService("Workspace"), ID, Pitch, Volume, true) --creates sound in workspace with your id,name,volume and pitch
