		notifSound:Destroy()
		game:GetService("StarterGui"):SetCore("SendNotification", {
			Title = "feFlip",
			Text = "feFlip loaded successfully!",
			Icon = "rbxassetid://505845268",
			Duration = 5,
			Button1 = "Okay"
		})
	end
})
