Main:AddButton({
	Title = "FE launch player High",
	Description = "launches desired player high (note) click Launch then quickly press unlaunch then after abt 10 seconds press it again and it should launch them hella high to stop just reset",
	Callback = function()
		local Players = game:GetService("Players")
		local Workspace = game:GetService("Workspace")
		local UserInputService = game:GetService("UserInputService")
		local RunService = game:GetService("RunService")
		local plr = game:service"Players".LocalPlayer;
		local tween_s = game:service"TweenService";
		local info = TweenInfo.new(10000,Enum.EasingStyle.Quad);
		function tp(...)
		local tic_k = tick();
		local params = {...};
		local cframe = CFrame.new(params[1],params[2],params[3]);
		local tween,err = pcall(function()
			local tween = tween_s:Create(plr.Character["HumanoidRootPart"],info,{CFrame=cframe});
			tween:Play();
		end)
		if not tween then return err end
		end
		local LocalPlayer = Players.LocalPlayer
		local Heartbeat = RunService.Heartbeat
		local Angles = CFrame.Angles
		local CFrame_new = CFrame.new
		local Vector3_new = Vector3.new

		local function findPlayer(name)
			for _, player in ipairs(Players:GetPlayers()) do
				if string.sub(string.lower(player.Name), 0, #name) == string.lower(name) or string.sub(string.lower(player.DisplayName), 0, #name) == string.lower(name) then
					return player
				end
			end
			return nil
		end

		local function layCharacterFlat(targetPlayer)
			local localCharacter = LocalPlayer.Character
			if not localCharacter then return end
			local localHumanoidRootPart = localCharacter:FindFirstChild("HumanoidRootPart")
			if not localHumanoidRootPart then return end

			local targetCharacter = targetPlayer.Character
			if not targetCharacter then return end
			local targetHumanoidRootPart = targetCharacter:FindFirstChild("HumanoidRootPart")
			if not targetHumanoidRootPart then return end

			-- Calculate the position underneath the target player's feet
			local targetFeetPosition = targetHumanoidRootPart.Position - Vector3_new(0, targetHumanoidRootPart.Size.Y + 1, 0)

			-- Lay the local character flat
			localHumanoidRootPart.CFrame = CFrame_new(targetFeetPosition) * Angles(math.pi / 2, 0, 0)
		end

		-- Creating a ScreenGui for the GUI
		local gui = Instance.new("ScreenGui")
		gui.Name = "CarpetGUI"
		gui.Parent = game:GetService("CoreGui")

		-- Creating the main Frame for the GUI
		local frame = Instance.new("Frame")
		frame.Size = UDim2.new(0, 200, 0, 150)
		frame.Position = UDim2.new(0.5, -100, 0.5, -50)
		frame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		frame.BorderSizePixel = 0
		frame.Parent = gui


		local textBox = Instance.new("TextBox")
		textBox.Size = UDim2.new(1, 0, 0, 20)
		textBox.Position = UDim2.new(0, 0, 0, 5)
		textBox.PlaceholderText = "Enter player name"
		textBox.Parent = frame

		local button = Instance.new("TextButton")
		button.Size = UDim2.new(1, 0, 0, 75)
		button.Position = UDim2.new(0, 0, 0, 30)
		button.Text = "Launch"
		button.Parent = frame

		local carpetEnabled = false
		local heartbeatConnection

		button.MouseButton1Click:Connect(function()
			local targetPlayerName = textBox.Text
			local targetPlayer = findPlayer(targetPlayerName)
			if targetPlayer then
				layCharacterFlat(targetPlayer)
			end

			carpetEnabled = not carpetEnabled
			if carpetEnabled then
				-- Function to update carpet position and local player's orientation
				local function updateCarpet()
					local player = findPlayer(textBox.Text)
					if player then
						local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
						if humanoid then
							local rootPart = player.Character:FindFirstChild("HumanoidRootPart")
							if rootPart then
								local carpet = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
								if carpet then
									carpet.CFrame = rootPart.CFrame * CFrame.new(0, -5, 0)
									layCharacterFlat(targetPlayer)
									carpet.Anchored = false
									tp(LocalPlayer.Character.HumanoidRootPart.Size.X, LocalPlayer.Character.HumanoidRootPart.Size.Y + 20000,LocalPlayer.Character.HumanoidRootPart.Size.Z)
								end
							end
						end
					end
				end
				-- Run update function every frame
				heartbeatConnection = Heartbeat:Connect(updateCarpet)
			else
				-- Disconnect the heartbeat to stop updating carpet position
				if heartbeatConnection then
					heartbeatConnection:Disconnect()
				end
			end
		end)

		local function dragify(frame)
			local UIS = game:GetService("UserInputService")
			local dragging
			local dragInput
			local dragStart
			local startPos

			local function update(input)
				local delta = input.Position - dragStart
				frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
			end

			frame.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
					dragging = true
					dragStart = input.Position
					startPos = frame.Position

					input.Changed:Connect(function()
						if input.UserInputState == Enum.UserInputState.End then
							dragging = false
						end
					end)
				end
			end)

			frame.InputChanged:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
					dragInput = input
				end
			end)

			UIS.InputChanged:Connect(function(input)
				if input == dragInput and dragging then
					update(input)
				end
			end)
		end

		dragify(frame)

	end
})
Main:AddButton({
	Title = "FE Player lifter",
	Description = "basically ascends anyone you click on",
	Callback = function()
		--Made by rouxhaver
        --super janky

        player = game:GetService("Players").LocalPlayer
        mouse = player:GetMouse()
        camera = game:GetService("Workspace").CurrentCamera
        ts = game:GetService("TweenService")

        function createtween(part, cframe,ttime)
        local tweeninfo = TweenInfo.new(ttime)
        tween = ts:Create(part, tweeninfo, {CFrame = cframe})
        tween:Play()
        tween.Completed:Wait()
        end

        outline = Instance.new("Highlight")

        target = nil

        mouse.Button1Up:Connect(function()
        if mouse.Target then
        local model = mouse.Target:FindFirstAncestorOfClass("Model")
        if model and model:FindFirstChild("Humanoid") then do
            camera.CameraSubject = model.Humanoid
            target = model
        end else
        outline.Parent = nil
        end
        end
        end)

        game:GetService("RunService").RenderStepped:Connect(function()
        if player.Character:FindFirstChild("HumanoidRootPart") then
        player.Character.HumanoidRootPart.Velocity = Vector3.new(0,0,0)
        if target and target:FindFirstChild("HumanoidRootPart") then
        if target.HumanoidRootPart.CFrame.Y + 20 < player.Character.HumanoidRootPart.CFrame.Y then
            tween:Cancel()
        end
        end
        end
        if mouse.Target then
        local model = mouse.Target:FindFirstAncestorOfClass("Model")
        if model and model:FindFirstChild("Humanoid") then do
            outline.Parent = model
        end else
        outline.Parent = nil
        end
        end
        end)

        while task.wait() do
        if target ~= nil and target:FindFirstAncestorOfClass("Workspace") and target ~= player.Character and player.Character:FindFirstChild("HumanoidRootPart") and target:FindFirstChild("HumanoidRootPart") then
        character = player.Character
        hrp = character.HumanoidRootPart
        thrp = target.HumanoidRootPart
        hrp.CFrame = thrp.CFrame * CFrame.Angles(math.rad(90),0,0) + thrp.CFrame.UpVector * -10
        end
        if target ~= nil and target:FindFirstAncestorOfClass("Workspace") and target ~= player.Character and player.Character:FindFirstChild("HumanoidRootPart") and target:FindFirstChild("HumanoidRootPart") then
        character = player.Character
        hrp = character.HumanoidRootPart
        thrp = target.HumanoidRootPart
        rot = thrp.CFrame*CFrame.Angles(math.rad(25),math.rad(25),math.rad(25))
        createtween(hrp, thrp.CFrame * CFrame.Angles(math.rad(90),0,0) + thrp.CFrame.UpVector * 1000000, 100000)
        end
        end
	end
})
