            Name = Name:lower()
            local Matches = {};
            for I = #Name,1,-1 do 
                for K,V in next, game:GetService('Players'):GetPlayers() do 
                    if rawequal(Name,V['Name']:lower():sub(1,I)) then 
                        table.insert(Matches,V)
                    end
                end
            end
            if #Matches > 0 then 
                return Matches[1]
