        --dragging script

        local function CHUYME_fake_script() -- Frame.draggable 
        local script = Instance.new('LocalScript', Frame)

        local UserInputService = game:GetService("UserInputService")
        local runService = (game:GetService("RunService"));
        
        local gui = script.Parent
        
        local dragging
        local dragInput
        local dragStart
        local startPos
        
        function Lerp(a, b, m)
        return a + (b - a) * m
        end;
        
        local lastMousePos
        local lastGoalPos
        local DRAG_SPEED = (12); -- // The speed of the UI darg.
        function Update(dt)
        if not (startPos) then return end;
        if not (dragging) and (lastGoalPos) then
        gui.Position = UDim2.new(startPos.X.Scale, Lerp(gui.Position.X.Offset, lastGoalPos.X.Offset, dt * DRAG_SPEED), startPos.Y.Scale, Lerp(gui.Position.Y.Offset, lastGoalPos.Y.Offset, dt * DRAG_SPEED))
        return 
        end;
        
        local delta = (lastMousePos - UserInputService:GetMouseLocation())
        local xGoal = (startPos.X.Offset - delta.X);
        local yGoal = (startPos.Y.Offset - delta.Y);
        lastGoalPos = UDim2.new(startPos.X.Scale, xGoal, startPos.Y.Scale, yGoal)
        gui.Position = UDim2.new(startPos.X.Scale, Lerp(gui.Position.X.Offset, xGoal, dt * DRAG_SPEED), startPos.Y.Scale, Lerp(gui.Position.Y.Offset, yGoal, dt * DRAG_SPEED))
        end;
        
        gui.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = gui.Position
        lastMousePos = UserInputService:GetMouseLocation()
        
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
            dragging = false
            end
        end)
        end
        end)
        
        gui.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        dragInput = input
        end
        end)
        
        runService.Heartbeat:Connect(Update)
        end
        coroutine.wrap(CHUYME_fake_script)()
        local function QYGCN_fake_script() -- Frame.close 
        local script = Instance.new('LocalScript', Frame)

        local frame = script.Parent.Parent.Frame
        
        script.Parent.MouseButton1Click:Connect(function()
        frame.Visible = false
        end)
        end
        if game:GetService("ReplicatedStorage"):FindFirstChild("DefaultChatSystemChatEvents") then
            game:GetService("ReplicatedStorage").DefaultChatSystemChatEvents.SayMessageRequest:FireServer("Boombox Supreme powers loaded" ,"All")
        else

        end
	end
})
Main:AddInput("TextboxIdentifier", {
	Title = "FE Play all boomboxes",
    Default = "Put Sound Id Here",
	Description = "Uses all the boomboxes in your inventory and plays them all at the same time",
    PlaceHolder = "Placeholder",
    Numeric = true,
    Finished = true,
	Callback = function(SoundId)
        local Settings = {
			[1] = "PlaySong",
			[2] = tonumber(SoundId)
		}

		for i, Boombox in next, game:GetService("Players").LocalPlayer:WaitForChild("Backpack"):GetChildren() do
			if (Boombox.Name == "Radio" or Boombox.Name == "Boombox") or (Boombox:FindFirstChild("Server") and Boombox:FindFirstChild("Client")) then
				Boombox.Parent = game:GetService("Players").LocalPlayer.Character
				Boombox.Remote:FireServer(unpack(Settings))
			end
		end
	end
})
Main:AddButton({
	Title = "FE Loop drop tools",
	Description = "only works if u spawn in with the tool. click again to stop and it adds 1 tool each time",
	Callback = function()
        

        local oldposti = game:GetService("Players").LocalPlayer.Character:WaitForChild("HumanoidRootPart").CFrame
        getgenv().lol = not getgenv().lol
        task.spawn(function()
            while true do task.wait()
                if not getgenv().lol then
                    wait(10)
                    game:GetService("Players").LocalPlayer.Character:WaitForChild("HumanoidRootPart").CFrame = oldposti
                    break
                end
                local tools = {}
                for i, v in pairs(game:GetService("Players").LocalPlayer:WaitForChild("Backpack"):GetDescendants()) do
                    if v:IsA("Tool") then
                        table.insert(tools, v)
                    end
                end


                for _, tool in ipairs(tools) do
                    toolPart = tool:FindFirstChildWhichIsA("Part")
                    if toolPart then
                        tool.Parent = game:GetService("Players").LocalPlayer.Character 
                        task.wait()
                        tool.Parent = game:GetService("Workspace")
                        task.wait()
                    end
                end
                game:GetService("Players").LocalPlayer.Character:WaitForChild("Humanoid").Health = 0
                wait(10)
                for i, v in pairs(game:GetService("Workspace"):GetChildren()) do
                    if v:IsA("Tool") then
                        game:GetService("Players").LocalPlayer.Character:WaitForChild("HumanoidRootPart").CFrame = v:FindFirstChildWhichIsA("Part").CFrame
                        task.wait(0.25)
                    end
                end
                wait(4)
                for i, v in pairs(game:GetService("Players").LocalPlayer.Character:GetChildren()) do
                    if v:IsA("Tool") then
                        v.Parent = game:GetService("Players").LocalPlayer:WaitForChild("Backpack")
                        task.wait()
                    end
                end
                wait(1)
            end
        end)
	end
})
