            for _,char in pairs(string:split("")) do
            wait(0.01)
            if char == " " then
            keypress(keys["space"])
            else
            if char:upper() == char and (char ~= "," and char ~= "." and char ~= "-" and char ~= "+" and char ~= "'" and char ~= '"' and char ~= "<" and char ~= ">" and char ~= "_" and char ~= "=") then
            keypress(keys["lshift"])
            keypress(keys[char:lower()])
                        keyrelease(keys["lshift"])
            else
            if char == "'" then
                keyrelease(keys["caps"])
                keyrelease(keys["lshift"])
                keypress(keys["quote"])
            elseif char == '"' then
                keyrelease(keys["caps"])
                keypress(keys["lshift"])
                keypress(keys["quote"])
                keyrelease(keys["lshift"])
            elseif char == "<" then
                keyrelease(keys["caps"])
                keypress(keys["lshift"])
                keypress(keys[","])
                keyrelease(keys["lshift"])
            elseif char == ">" then
                keyrelease(keys["caps"])
                keypress(keys["lshift"])
                keypress(keys["."])
                keyrelease(keys["lshift"])
            elseif char == "_" then
                keyrelease(keys["caps"])
                keypress(keys["lshift"])
                keypress(keys["-"])
                keyrelease(keys["lshift"])
            elseif char == "=" then
                keyrelease(keys["caps"])
                keypress(keys["lshift"])
                keypress(keys["+"])
                keyrelease(keys["lshift"])
            else
                keyrelease(keys["caps"])
                keyrelease(keys["lshift"])
                keypress(keys[char])
